#include "hybrid_window_adapter.h"
namespace attention_dispatcher { namespace {bool ok(const HybridWindowContract&c,std::string&e){if(c.batch<=0||c.time<=0||c.height<=0||c.width<=0||c.channels<=0||c.window_t<=0||c.window_h<=0||c.window_w<=0||c.grid_t*c.window_t!=c.time+c.pad_t||c.grid_h*c.window_h!=c.height+c.pad_h||c.grid_w*c.window_w!=c.width+c.pad_w||c.pad_t<0||c.pad_h<0||c.pad_w<0){e="invalid hybrid window contract";return false;}return true;}}
bool pack_hybrid_windows(const std::vector<float>&x,const HybridWindowContract&c,std::vector<float>&w,std::string&e){if(!ok(c,e)||x.size()!=size_t(c.batch)*c.time*c.height*c.width*c.channels){e="hybrid pack input/contract mismatch";return false;}w.assign(size_t(c.batch)*c.grid_t*c.grid_h*c.grid_w*c.window_t*c.window_h*c.window_w*c.channels,0);for(int b=0;b<c.batch;++b)for(int gt=0;gt<c.grid_t;++gt)for(int gh=0;gh<c.grid_h;++gh)for(int gw=0;gw<c.grid_w;++gw)for(int t=0;t<c.window_t;++t)for(int h=0;h<c.window_h;++h)for(int q=0;q<c.window_w;++q)for(int ch=0;ch<c.channels;++ch){int T=gt*c.window_t+t,H=gh*c.window_h+h,W=gw*c.window_w+q;auto di=((((((size_t(b)*c.grid_t+gt)*c.grid_h+gh)*c.grid_w+gw)*c.window_t+t)*c.window_h+h)*c.window_w+q)*c.channels+ch;if(T<c.time&&H<c.height&&W<c.width)w[di]=x[((((size_t(b)*c.time+T)*c.height+H)*c.width+W)*c.channels+ch)];}e.clear();return true;}
bool unpack_hybrid_windows(const std::vector<float>&w,const HybridWindowContract&c,std::vector<float>&x,std::string&e){if(!ok(c,e)||w.size()!=size_t(c.batch)*c.grid_t*c.grid_h*c.grid_w*c.window_t*c.window_h*c.window_w*c.channels){e="hybrid unpack input/contract mismatch";return false;}x.assign(size_t(c.batch)*c.time*c.height*c.width*c.channels,0);for(int b=0;b<c.batch;++b)for(int gt=0;gt<c.grid_t;++gt)for(int gh=0;gh<c.grid_h;++gh)for(int gw=0;gw<c.grid_w;++gw)for(int t=0;t<c.window_t;++t)for(int h=0;h<c.window_h;++h)for(int q=0;q<c.window_w;++q)for(int ch=0;ch<c.channels;++ch){int T=gt*c.window_t+t,H=gh*c.window_h+h,W=gw*c.window_w+q;if(T<c.time&&H<c.height&&W<c.width)x[((((size_t(b)*c.time+T)*c.height+H)*c.width+W)*c.channels+ch)]=w[((((((size_t(b)*c.grid_t+gt)*c.grid_h+gh)*c.grid_w+gw)*c.window_t+t)*c.window_h+h)*c.window_w+q)*c.channels+ch];}e.clear();return true;}}
